[
  {
    "text": "Partial observability alone necessitates the maintenance of some internal state to recover missing information, but does not mandate that this state take the form of an explicit, translatable long-term memory.",
    "topic": "Partial observability and state representation"
  },
  {
    "text": "The need to translate long-term memory into embodied plans arises only when the internal state is an explicit, overwritable world model that can be corrupted by contradictory observations.",
    "topic": "Overwritable world model requirement"
  },
  {
    "text": "Reactive policy benchmarks show that implicit state representations (e.g., in RNNs) can successfully handle partial observability and overwritten world states without a discrete long-term-memory-to-plan translation step.",
    "topic": "Implicit state counterexample"
  },
  {
    "text": "The WorldLines hypothesis applies to integration only if the integration mechanism relies on an explicit, overwritable declarative memory, not to systems using sub-symbolic or implicit memory.",
    "topic": "Scope of hypothesis"
  }
]
